namespace CanDoItAll.SharedProviders.TestUpstream;

internal sealed record FixtureImage(string Format, string ContentType, byte[] Bytes);

internal static class FixtureImages
{
    private static readonly IReadOnlyDictionary<string, FixtureImage> Images =
        new Dictionary<string, FixtureImage>(StringComparer.Ordinal)
        {
            ["png"] = new(
                "png",
                "image/png",
                Convert.FromBase64String(
                    "iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAQAAAC1HAwCAAAAC0lEQVR42mP8/x8AAwMCAO+jmioAAAAASUVORK5CYII=")),
            ["jpeg"] = new(
                "jpeg",
                "image/jpeg",
                Convert.FromBase64String(
                    "")),
            ["webp"] = new(
                "webp",
                "image/webp",
                Convert.FromBase64String(
                    ""))
        };

    public static bool TryGet(string? format, out FixtureImage image)
        => Images.TryGetValue(format?.Trim().ToLowerInvariant() ?? string.Empty, out image!);
}
